INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Share repurchase effect on EPS
(4, 'Capital Structure and Valuation', 'Alderton Industries is an all-equity firm with 2,000,000 shares outstanding and net income of $6,000,000. The current stock price is $25. The board authorizes a repurchase of 400,000 shares at market price using excess cash. What is the most likely effect on earnings per share?', '["EPS decreases because the cash outflow reduces total stockholders'' equity", "EPS remains unchanged because the repurchase proportionally reduces both equity and share count", "EPS increases from $3.00 to $3.75 because fewer shares are outstanding while net income is unchanged", "EPS doubles to $6.00 because treasury shares are treated as retired"]'::jsonb, 2, 'Under ASC 505-30, treasury stock transactions reduce shares outstanding without affecting net income. EPS rises from $6,000,000 ÷ 2,000,000 = $3.00 to $6,000,000 ÷ 1,600,000 = $3.75 because the denominator decreases while the numerator stays constant. Choice B is incorrect because a share repurchase does not reduce earnings—it reduces cash and equity but net income remains the same, so EPS must increase.', 'medium', 3),

-- Q2: easy / L1 — Systematic risk definition
(4, 'Capital Structure and Valuation', 'In portfolio theory, systematic risk is best described as:', '["Risk that affects the entire market and cannot be eliminated through diversification", "Risk unique to a specific company that can be reduced by holding more securities", "The total variability of a single security measured by standard deviation", "Risk arising solely from poor corporate governance within a firm"]'::jsonb, 0, 'Under the Capital Asset Pricing Model (CAPM), systematic risk—also called market or non-diversifiable risk—affects all securities and is measured by beta. It arises from macroeconomic factors such as interest rates, inflation, and recessions that cannot be diversified away. Choice B describes unsystematic (firm-specific) risk, which is diversifiable and not compensated in equilibrium pricing.', 'easy', 1),

-- Q3: easy / L1 — Capital structure definition
(4, 'Capital Structure and Valuation', 'A firm''s capital structure refers to:', '["The total dollar amount of assets reported on the balance sheet", "The mix of debt and equity financing used to fund the firm''s operations", "The allocation of operating expenses across business segments", "The ratio of current assets to current liabilities"]'::jsonb, 1, 'Capital structure, as analyzed under Modigliani-Miller theory and reflected in ASC 470 (debt) and ASC 505 (equity), describes the proportion of debt and equity a firm uses to finance its operations. The optimal mix minimizes WACC and maximizes firm value. Choice D describes the current ratio, a liquidity measure unrelated to long-term financing decisions.', 'easy', 1),

-- Q4: medium / L3 — Rising interest rates effect on WACC
(4, 'Capital Structure and Valuation', 'Brookfield Industries has a target capital structure of 40% debt and 60% equity. The Federal Reserve announces a 150-basis-point increase in the federal funds rate. Brookfield''s credit spread remains unchanged, but the risk-free rate rises accordingly. What is the most likely effect on Brookfield''s weighted average cost of capital?', '["WACC is unchanged because the tax shield on debt fully offsets the higher interest rate", "Only the cost of debt increases; the cost of equity is unaffected by risk-free rate changes", "WACC decreases because higher rates attract more lenders, reducing borrowing costs", "WACC increases because both the cost of debt and the CAPM-based cost of equity rise with the risk-free rate"]'::jsonb, 3, 'Under CAPM, the cost of equity equals the risk-free rate plus beta times the market risk premium. A higher risk-free rate directly increases both the pre-tax cost of debt (base rate plus credit spread) and the CAPM-derived cost of equity, pushing WACC higher on both components. Choice B is incorrect because CAPM explicitly includes the risk-free rate, so equity costs rise as well.', 'medium', 3),

-- Q5: hard / L4 — Evaluate recapitalization with distress costs
(4, 'Capital Structure and Valuation', 'Castleford Enterprises (BBB-rated, D/E ratio of 0.8) considers issuing $30,000,000 in new debt to repurchase shares. The CFO estimates the incremental annual tax shield at $1,575,000, but the treasurer warns that a probable downgrade to BB would raise borrowing costs by 200 basis points on all $75,000,000 of existing debt. Evaluate whether the recapitalization maximizes firm value.', '["The recapitalization likely destroys value because the $1,500,000 annual increase in existing debt costs nearly eliminates the tax shield before considering indirect distress costs", "The recapitalization clearly increases firm value because the incremental tax shield is positive", "The recapitalization is value-neutral because the tax shield and higher borrowing costs exactly offset each other", "The recapitalization increases value because fixed-rate bonds are unaffected by credit rating changes"]'::jsonb, 0, 'Under the trade-off theory of capital structure, the optimal debt level balances tax shield benefits against financial distress costs. The 200-basis-point increase on $75,000,000 existing debt adds $1,500,000 in annual cost, nearly wiping out the $1,575,000 tax shield—and this ignores indirect costs such as customer and supplier attrition. Choice B is incorrect because it considers only the benefit side, ignoring the escalation of distress costs.', 'hard', 4),

-- Q6: medium / L2 — Economic value added (EVA) calculation
(4, 'Capital Structure and Valuation', 'Drayton Manufacturing reports net operating profit after tax (NOPAT) of $4,200,000 and has total invested capital of $28,000,000. The firm''s WACC is 12%. What is Drayton''s economic value added?', '["$504,000", "$4,200,000", "$840,000", "$3,360,000"]'::jsonb, 2, 'Economic value added equals NOPAT minus the capital charge: $4,200,000 − (12% × $28,000,000) = $4,200,000 − $3,360,000 = $840,000. A positive EVA indicates the firm earns above its cost of capital, creating shareholder value. Choice D ($3,360,000) incorrectly reports the capital charge itself rather than the residual after subtracting it from NOPAT.', 'medium', 2),

-- Q7: medium / L2 — Free cash flow to firm (FCFF)
(4, 'Capital Structure and Valuation', 'Eastfield Corp. reports EBIT of $8,000,000, depreciation of $1,000,000, capital expenditures of $1,500,000, and an increase in net working capital of $500,000. The tax rate is 25%. What is Eastfield''s free cash flow to the firm?', '["$6,000,000", "$5,000,000", "$5,500,000", "$4,000,000"]'::jsonb, 1, 'Free cash flow to the firm equals EBIT × (1 − tax rate) + depreciation − capital expenditures − change in working capital: $8,000,000 × 0.75 + $1,000,000 − $1,500,000 − $500,000 = $5,000,000. FCFF represents cash available to all capital providers. Choice A ($6,000,000) is the common error of using only NOPAT without adjusting for reinvestment and working capital needs.', 'medium', 2),

-- Q8: medium / L3 — Covenant violation effect on cost of capital
(4, 'Capital Structure and Valuation', 'Fairmont Holdings violates its debt-to-EBITDA covenant of 4.0× when the ratio reaches 4.3× after an earnings miss. The lender accelerates the loan and demands renegotiation at a 175-basis-point premium. What is the most likely effect on Fairmont''s overall cost of capital?', '["Only the cost of debt increases; equity holders are unaffected by the covenant breach", "Cost of capital decreases because the waiver process demonstrates lender willingness to support the firm", "Cost of capital is unchanged because the violation is temporary and curable", "Both cost of debt and cost of equity increase due to heightened default risk perceptions"]'::jsonb, 3, 'Under the trade-off theory, covenant violations elevate financial distress risk. Lenders demand higher spreads for waivers (increasing cost of debt), while equity holders—as subordinate claimants—face amplified residual risk and require higher returns (increasing cost of equity). Both effects push WACC higher. Choice A is incorrect because equity is junior to debt, so heightened default risk increases equity risk as well.', 'medium', 3),

-- Q9: medium / L2 — Enterprise value calculation
(4, 'Capital Structure and Valuation', 'Glenmore Corp. has 5,000,000 shares outstanding at a market price of $32, total debt of $45,000,000, and cash and equivalents of $12,000,000. What is Glenmore''s enterprise value?', '["$193,000,000", "$205,000,000", "$160,000,000", "$127,000,000"]'::jsonb, 0, 'Enterprise value equals market capitalization plus total debt minus cash: (5,000,000 × $32) + $45,000,000 − $12,000,000 = $193,000,000. EV represents the total cost to acquire the firm''s operations, net of liquid assets an acquirer would receive. Choice B ($205,000,000) omits the cash subtraction, overstating the net acquisition cost.', 'medium', 2),

-- Q10: medium / L2 — Residual income calculation
(4, 'Capital Structure and Valuation', 'Hartwell Investments manages a division with net operating income of $3,600,000 and average operating assets of $24,000,000. The corporate required rate of return is 12%. What is the division''s residual income?', '["$2,880,000", "$720,000", "$3,600,000", "$432,000"]'::jsonb, 1, 'Residual income equals net operating income minus the capital charge: $3,600,000 − (12% × $24,000,000) = $3,600,000 − $2,880,000 = $720,000. A positive residual income means the division earns above its required return on invested capital. Choice A ($2,880,000) reports the capital charge itself rather than the amount by which earnings exceed it.', 'medium', 2),

-- Q11: medium / L3 — Credit rating downgrade effect on optimal structure
(4, 'Capital Structure and Valuation', 'Ironbridge Logistics is downgraded from A- to BBB after taking on significant acquisition debt. Bond spreads widen by 120 basis points and the equity beta increases from 1.1 to 1.4. What is the most likely impact on Ironbridge''s optimal capital structure?', '["The firm should add more debt to exploit the still-investment-grade rating before further downgrades", "The downgrade has no practical effect because BBB remains investment grade", "The higher cost of both debt and equity reduces the net benefit of leverage, shifting the optimum toward less debt", "The wider bond spread is offset by lower equity costs as bondholders now absorb more risk"]'::jsonb, 2, 'Under the trade-off theory (Modigliani-Miller with frictions), the optimal capital structure balances tax shield benefits against distress costs. A downgrade increases both borrowing costs and equity risk (reflected in the higher beta), reducing the marginal benefit of leverage and shifting the optimum toward less debt. Choice D is incorrect because equity is subordinate to debt—when debt risk rises, equity risk increases as well.', 'medium', 3),

-- Q12: medium / L2 — Equity value via Gordon growth model
(4, 'Capital Structure and Valuation', 'Juniper Technologies generates free cash flow to equity of $2,400,000 per year, expected to grow at 3% indefinitely. The cost of equity is 11%. Using the constant-growth model, what is the estimated equity value?', '["$30,000,000", "$21,818,182", "$80,000,000", "$17,142,857"]'::jsonb, 0, 'Using the Gordon growth model, equity value equals FCFE ÷ (cost of equity − growth rate) = $2,400,000 ÷ (0.11 − 0.03) = $30,000,000. The denominator is the spread between the discount rate and the perpetual growth rate. Choice B ($21,818,182) divides by the cost of equity alone, ignoring the growth component, which significantly understates equity value.', 'medium', 2),

-- Q13: medium / L3 — M-M dividend irrelevance real-world deviation
(4, 'Capital Structure and Valuation', 'Kensington Partners declares a special $5.00 dividend when its stock trades at $60.00. The CFO argues the payout boosts shareholder wealth. Under Miller-Modigliani dividend irrelevance, the stock should drop to approximately $55.00 ex-dividend. What real-world factor most likely causes the actual price impact to deviate from M-M''s prediction?', '["The firm''s debt-to-equity ratio exceeds 1.0", "The dividend is funded from retained earnings rather than new borrowing", "The company''s equity beta is above the market average", "Differential tax treatment of dividends versus capital gains for investors"]'::jsonb, 3, 'Modigliani-Miller (1961) showed dividend policy is irrelevant in perfect markets. In practice, dividends and capital gains are taxed at different rates, creating investor tax clienteles that cause the ex-dividend price drop to differ from the full dividend amount. This tax wedge violates M-M''s no-tax assumption. Choice B is incorrect because M-M irrelevance holds regardless of the funding source in a perfect market.', 'medium', 3),

-- Q14: easy / L2 — Terminal value calculation
(4, 'Capital Structure and Valuation', 'Lakeshore Analytics projects Year 5 free cash flow of $1,800,000 with a perpetual growth rate of 2% and a WACC of 10%. What is the terminal value at the end of Year 5?', '["$18,000,000", "$22,950,000", "$22,500,000", "$15,000,000"]'::jsonb, 1, 'Terminal value using the Gordon growth model equals FCF₅ × (1 + g) ÷ (WACC − g) = $1,800,000 × 1.02 ÷ 0.08 = $22,950,000. The (1 + g) factor grows the final projected cash flow forward one period to capture the first year of the perpetuity. Choice C ($22,500,000) omits this growth factor, understating terminal value by one year''s growth.', 'easy', 2),

-- Q15: medium / L2 — P/E comparable valuation
(4, 'Capital Structure and Valuation', 'Merriweather Foods trades at $48.00 with earnings per share of $3.20. A comparable firm, Northland Provisions, trades at a P/E of 18×. Based on the comparable company approach, what is the implied assessment of Merriweather''s valuation?', '["Merriweather''s P/E of 20× indicates it is overvalued relative to Northland", "P/E ratios are not valid for cross-company comparisons within the same industry", "Merriweather''s P/E of 15× suggests it is undervalued relative to Northland''s 18×", "Merriweather''s P/E of 15× suggests it is overvalued relative to Northland''s 18×"]'::jsonb, 2, 'The price-to-earnings ratio equals price ÷ EPS = $48.00 ÷ $3.20 = 15×. Since the comparable company trades at 18×, Merriweather trades at a discount, suggesting potential undervaluation if risk profiles are similar. Choice D correctly computes the 15× ratio but draws the wrong conclusion—a lower P/E relative to a comparable indicates the market assigns a lower valuation multiple, not overvaluation.', 'medium', 2),

-- Q16: medium / L3 — Convertible bond dilution on EPS
(4, 'Capital Structure and Valuation', 'Oakmont Corp. has net income of $12,000,000 and 5,000,000 shares outstanding. The firm has $25,000,000 of 4% convertible bonds, each $1,000 par bond convertible into 40 common shares. The tax rate is 25%. What is the effect on diluted EPS compared to basic EPS of $2.40?', '["Diluted EPS of $2.13 is lower than basic EPS, reflecting the dilutive effect of potential conversion", "Diluted EPS equals $2.40 because convertible bonds are always antidilutive", "Diluted EPS of $2.55 because the interest savings exceed dilution from additional shares", "Diluted EPS of $2.00 because the full principal amount reduces net income"]'::jsonb, 0, 'Under ASC 260, diluted EPS assumes conversion: add back after-tax interest ($25,000,000 × 4% × 0.75 = $750,000) and add conversion shares (25,000 bonds × 40 = 1,000,000). Diluted EPS = ($12,000,000 + $750,000) ÷ 6,000,000 = $2.13, below basic EPS of $2.40, confirming dilution. Choice B is incorrect because the conversion is dilutive whenever diluted EPS falls below basic EPS.', 'medium', 3),

-- Q17: medium / L2 — Book value per common share
(4, 'Capital Structure and Valuation', 'Pembridge Holdings reports total assets of $85,000,000, total liabilities of $52,000,000, and preferred stock of $5,000,000. The firm has 4,000,000 common shares outstanding. What is the book value per common share?', '["$8.25", "$21.25", "$13.00", "$7.00"]'::jsonb, 3, 'Book value per common share equals (total assets − total liabilities − preferred stock) ÷ common shares: ($85,000,000 − $52,000,000 − $5,000,000) ÷ 4,000,000 = $7.00. Preferred stock must be subtracted because it represents a senior equity claim ahead of common shareholders. Choice A ($8.25) fails to deduct the $5,000,000 preferred stock, overstating common shareholders'' residual interest.', 'medium', 2),

-- Q18: hard / L3 — Adjusted present value (APV) method
(4, 'Capital Structure and Valuation', 'Ridgeway Corp. evaluates an acquisition using the adjusted present value method. The target''s unlevered free cash flows have a present value of $40,000,000. The deal will be financed with $18,000,000 of permanent debt at 6% interest. The tax rate is 25%, and the estimated present value of financial distress costs is $1,200,000. What is the APV of the acquisition?', '["$44,500,000", "$43,300,000", "$38,800,000", "$34,300,000"]'::jsonb, 1, 'The adjusted present value method values a project as unlevered value plus PV of financing side effects: APV = $40,000,000 + ($18,000,000 × 25%) − $1,200,000 = $40,000,000 + $4,500,000 − $1,200,000 = $43,300,000. The tax shield on permanent debt equals D × T. Choice A ($44,500,000) ignores financial distress costs, which the trade-off theory recognizes as an essential offset to tax shield benefits.', 'hard', 3),

-- Q19: hard / L4 — Lease vs. buy capital structure evaluation
(4, 'Capital Structure and Valuation', 'Silverton Manufacturing needs a $6,000,000 machine. Option A is a 7-year finance lease with annual payments of $1,050,000. Option B is an outright purchase funded by a 7-year bank loan at 6.5%. Under ASC 842, the finance lease records both a right-of-use asset and a lease liability. The CFO argues that leasing avoids increasing leverage. Evaluate this assumption.', '["The lease avoids leverage because lease payments are classified as operating expenses", "The loan is preferable because finance leases always create higher total interest expense", "The assumption is incorrect because ASC 842 requires finance leases to record a liability comparable to debt, so leverage increases either way", "The lease reduces leverage because the right-of-use asset fully offsets the lease liability on the balance sheet"]'::jsonb, 2, 'Under ASC 842, finance leases require recognition of both a right-of-use asset and a lease liability on the balance sheet, economically equivalent to debt. The CFO''s belief that leasing avoids leverage reflects a common misconception from pre-ASC 842 treatment of operating leases. Choice A is incorrect because ASC 842 requires on-balance-sheet recognition for virtually all leases exceeding 12 months.', 'hard', 4),

-- Q20: easy / L2 — Bond yield plus risk premium method
(4, 'Capital Structure and Valuation', 'Thornton Enterprises'' long-term bonds yield 7.5%. Using the bond-yield-plus-risk-premium approach with a 4% equity risk premium, what is the estimated cost of equity?', '["11.5%", "7.5%", "3.5%", "4.0%"]'::jsonb, 0, 'The bond-yield-plus-risk-premium method estimates cost of equity by adding an equity risk premium to the firm''s own bond yield: 7.5% + 4.0% = 11.5%. This approach recognizes that equity is riskier than debt and requires a premium above the firm''s borrowing cost. Choice B (7.5%) uses only the bond yield, which reflects the cost of debt, not the higher return equity investors require.', 'easy', 2),

-- Q21: hard / L4 — Evaluate debt vs. equity issuance decision
(4, 'Capital Structure and Valuation', 'Waverly Technologies (D/E 0.3, stock at an all-time high P/E of 35×) needs $40,000,000 for an acquisition. The CFO favors equity to exploit the high valuation; the treasurer argues for debt at 5.5% to preserve EPS accretion. The acquisition''s expected return is 11% against a 9% WACC. Evaluate which approach better serves shareholders.', '["Equity is always preferable when the stock trades at a historically high P/E multiple", "Debt is always preferred because it preserves existing shareholder ownership percentages", "The financing decision is irrelevant because Modigliani-Miller proves capital structure does not matter", "Equity at a high P/E limits dilution, but the tax benefit of debt and negative signaling of equity issuance must also be weighed"]'::jsonb, 3, 'Under signaling theory (Myers-Majluf, 1984), new equity issuance typically depresses stock prices because it signals management believes shares are overvalued. However, issuing at a high multiple minimizes dilution cost. Debt at 5.5% after tax is cheaper and preserves upside. The decision requires weighing tax benefits of debt against dilution and signaling costs of equity. Choice C misapplies M-M Proposition I, which holds only in frictionless markets.', 'hard', 4),

-- Q22: easy / L1 — Unsystematic (diversifiable) risk
(4, 'Capital Structure and Valuation', 'Unsystematic risk is best described as:', '["Risk arising from macroeconomic factors that affects all securities in the market", "Risk specific to an individual company or industry that can be eliminated through diversification", "The risk measured by a security''s beta coefficient in the CAPM framework", "Risk that increases proportionally with the number of securities in a portfolio"]'::jsonb, 1, 'Unsystematic risk (also called firm-specific or diversifiable risk) arises from factors unique to a particular company, such as management changes, product recalls, or labor strikes. Modern portfolio theory demonstrates this risk can be virtually eliminated by holding a well-diversified portfolio. Choice A describes systematic (market) risk, which cannot be diversified away and is the only risk compensated in equilibrium.', 'easy', 1),

-- Q23: easy / L1 — WACC as hurdle rate
(4, 'Capital Structure and Valuation', 'In capital budgeting, WACC is most commonly used as:', '["The minimum required return a project must earn to create shareholder value", "The maximum return a firm can earn on any investment opportunity", "The interest rate the firm pays on its most recent bond issuance", "The historical average return on the firm''s common stock"]'::jsonb, 0, 'WACC represents the blended cost of all capital sources and serves as the hurdle rate for capital budgeting decisions. A project earning above WACC has a positive NPV and creates value; one earning below WACC destroys value. This principle is foundational to corporate finance and NPV analysis. Choice C confuses WACC with the cost of debt alone, which is only one component of the weighted average.', 'easy', 1),

-- Q24: medium / L3 — Diluted EPS with stock options (treasury stock method)
(4, 'Capital Structure and Valuation', 'Pinnacle Systems has net income of $8,000,000 and 2,000,000 basic shares outstanding. Management holds 200,000 stock options with an exercise price of $20 when the average market price is $40. Using the treasury stock method under ASC 260, what is the most likely effect on diluted EPS?', '["Diluted EPS equals basic EPS of $4.00 because stock options are always antidilutive", "Diluted EPS drops to $3.64 because all 200,000 option shares are added to the denominator", "Diluted EPS drops to $3.81 because the treasury stock method adds only the net incremental 100,000 shares", "Diluted EPS increases above $4.00 because option exercises generate cash inflow"]'::jsonb, 2, 'Under ASC 260, the treasury stock method assumes option proceeds ($20 × 200,000 = $4,000,000) repurchase shares at the $40 average market price (100,000 shares), yielding a net increment of 100,000 shares. Diluted EPS = $8,000,000 ÷ 2,100,000 = $3.81. Choice B ($3.64) incorrectly adds all 200,000 option shares without offsetting for the assumed treasury stock repurchase.', 'medium', 3),

-- Q25: easy / L2 — Market capitalization calculation
(4, 'Capital Structure and Valuation', 'Redstone Industries has 3,500,000 shares of common stock outstanding trading at $28 per share, and 500,000 shares of preferred stock at $50 per share. What is the common equity market capitalization?', '["$123,000,000", "$25,000,000", "$73,000,000", "$98,000,000"]'::jsonb, 3, 'Common equity market capitalization equals common shares outstanding multiplied by market price per share: 3,500,000 × $28 = $98,000,000. Preferred stock is a separate class of equity excluded from this measure. Choice A ($123,000,000) incorrectly adds the preferred stock market value ($500,000 × $50 = $25,000,000), which overstates the common equity component.', 'easy', 2),

-- Q26: easy / L1 — Operating leverage definition
(4, 'Capital Structure and Valuation', 'Operating leverage is best defined as:', '["The proportion of a firm''s total financing that comes from debt instruments", "The degree to which a firm uses fixed operating costs, causing operating income to be more sensitive to sales changes", "The ratio of current assets to current liabilities on the balance sheet", "The practice of using retained earnings instead of external financing sources"]'::jsonb, 1, 'Operating leverage measures how sensitive operating income (EBIT) is to changes in sales revenue, driven by the proportion of fixed versus variable costs in the cost structure. A firm with high fixed costs has high operating leverage—small sales changes produce large EBIT swings. Choice A describes financial leverage (the use of debt), which is a separate concept affecting earnings below the EBIT line.', 'easy', 1),

-- Q27: medium / L3 — Asset beta vs. equity beta analysis
(4, 'Capital Structure and Valuation', 'Stratton Corp. has an equity beta of 1.6, a D/E ratio of 1.0, and a tax rate of 25%. A financial analyst unleverages the beta to estimate Stratton''s asset beta. What does the difference between equity beta and asset beta reveal about Stratton''s risk profile?', '["The unlevered beta of 0.91 shows that roughly 43% of Stratton''s equity risk comes from financial leverage rather than business operations", "The unlevered beta exceeds the equity beta because removing leverage increases measured operational risk", "The unlevered beta equals the equity beta because leverage does not affect systematic risk", "The unlevered beta is negative because debt reduces overall firm risk below zero"]'::jsonb, 0, 'Using the Hamada equation, asset beta = 1.6 ÷ (1 + 0.75 × 1.0) = 0.91. The gap between equity beta (1.6) and asset beta (0.91) shows about 43% of equity risk is attributable to financial leverage rather than underlying business risk. Choice C is incorrect because leverage amplifies equity beta above asset beta, as the Hamada equation directly demonstrates.', 'medium', 3),

-- Q28: hard / L4 — Capital rationing evaluation
(4, 'Capital Structure and Valuation', 'Wentworth Capital has a $15,000,000 capital budget and four independent projects: Project A costs $6,000,000 (NPV $1,800,000), Project B costs $5,000,000 (NPV $1,600,000), Project C costs $8,000,000 (NPV $2,100,000), and Project D costs $4,000,000 (NPV $950,000). All exceed the 10% hurdle rate. Evaluate which combination maximizes total NPV under the budget constraint.', '["Projects A and C ($14,000,000 invested, $3,900,000 total NPV)", "Projects C and D ($12,000,000 invested, $3,050,000 total NPV)", "Project C alone because it has the single highest NPV of $2,100,000", "Projects A, B, and D ($15,000,000 invested, $4,350,000 total NPV)"]'::jsonb, 3, 'Under capital rationing, the objective is to maximize total NPV within the budget constraint. Projects A + B + D use exactly $15,000,000 and generate $4,350,000 in combined NPV, exceeding all other feasible combinations. The profitability index (NPV ÷ cost) helps rank projects, but the final decision requires testing feasible combinations. Choice A ($3,900,000 from A + C) leaves $1,000,000 undeployed and produces less total value.', 'hard', 4),

-- Q29: easy / L1 — Security market line
(4, 'Capital Structure and Valuation', 'The security market line (SML) graphically represents:', '["The relationship between a portfolio''s total risk and its expected return", "The historical return of a stock plotted against its trading volume", "The relationship between a security''s beta and its required return as predicted by CAPM", "The trade-off between a firm''s debt ratio and its cost of equity"]'::jsonb, 2, 'The security market line plots expected return against beta (systematic risk) for all securities, as derived from the Capital Asset Pricing Model. Securities above the SML are undervalued; those below are overvalued. Choice A describes the capital market line (CML), which uses total risk (standard deviation) rather than beta on the horizontal axis.', 'easy', 1),

-- Q30: hard / L4 — Real-world capital structure vs. M-M
(4, 'Capital Structure and Valuation', 'Prescott Holdings is an all-equity firm with a WACC of 13% and stable EBITDA of $20,000,000 with minimal cyclicality. The firm has an investment-grade credit profile. A newly hired CFO proposes adding moderate leverage. Using the trade-off framework, evaluate whether the proposal is likely to create value.', '["Debt would destroy value because interest payments reduce free cash flow available to equity holders", "Debt is likely value-creating because stable cash flows support reliable interest coverage, and the tax shield benefit outweighs distress costs at moderate leverage", "Debt is irrelevant because Modigliani-Miller Proposition I applies regardless of real-world frictions", "Debt decreases WACC only if the firm eliminates all equity financing entirely"]'::jsonb, 1, 'Under the trade-off theory, firms with stable, predictable cash flows and strong credit profiles benefit most from moderate leverage because distress probability is low, allowing the tax shield to dominate. Prescott''s stable $20,000,000 EBITDA and investment-grade profile suggest moderate debt would reduce WACC and increase firm value. Choice C misapplies M-M Proposition I, which holds only in frictionless markets—real-world taxes create a clear benefit to debt.', 'hard', 4)
;

COMMIT;
